const diagnosticQuestions = [
  { id:'channel', label:'أغلب الطلب بيجيلك منين؟', options:[['social','Instagram / WhatsApp'],['marketplace','Marketplace'],['store','متجر موجود'],['mixed','أكثر من قناة']] },
  { id:'stage', label:'أنت في أي مرحلة؟', options:[['new','لسه هنبدأ'],['leaking','عندي طلب والرحلة بتسرّب'],['scaling','عندي متجر وعايز أكبر'],['rebuild','عايز أعيد البناء']] },
  { id:'catalog', label:'حجم الكتالوج تقريبًا؟', options:[['small','أقل من ٣٠ منتج'],['medium','٣٠–١٥٠ منتج'],['large','أكثر من ١٥٠ منتج']] },
  { id:'pain', label:'أكبر مشكلة دلوقتي؟', options:[['checkout','Checkout / دفع / COD'],['catalog','ترتيب المنتجات والمحتوى'],['tracking','Tracking وقياس'],['launch','إطلاق متجر من الصفر']] }
];
function CommerceDiagnostic({onComplete}){
  const [step,setStep]=useState(0),[answers,setAnswers]=useState({}),[result,setResult]=useState(null);
  const answer=(id,value)=>{const next={...answers,[id]:value};setAnswers(next);if(step<diagnosticQuestions.length-1)setStep(step+1);else{const recommendation=next.stage==='new'?'Starter':next.stage==='scaling'?'Business':next.pain==='checkout'?'Commerce':next.pain==='launch'?'Store Launch':'Business';const insight=next.pain==='checkout'?'أكبر فرصة عندك غالبًا في تقليل الاحتكاك بين المنتج والدفع.':next.pain==='tracking'?'قبل أي إنفاق إضافي، ثبّت القياس واعرف أين تتسرب الطلبات.':next.channel==='social'?'نحتاج نحول الطلب المتناثر من السوشيال إلى قناة مملوكة قابلة للقياس.':'نبدأ من ترتيب الرحلة والكتالوج قبل ما نكبر التنفيذ.';const value={recommendation,insight,answers:next};setResult(value);onComplete?.(value)}};
  if(result)return <div className="diagnostic-result"><div className="result-signal"><Sparkles size={20}/> قراءة أولية</div><h3>الخطوة الأقرب لحالتك: <em>{result.recommendation}</em></h3><p>{result.insight}</p><a className="button primary" href="#contact">كمّل بالـBrief <ArrowLeft size={17}/></a><button className="diagnostic-reset" onClick={()=>{setStep(0);setAnswers({});setResult(null)}}>ابدأ من جديد</button></div>;
  const q=diagnosticQuestions[step];
  return <div className="diagnostic-card"><div className="diagnostic-top"><span>COMMERCE DIAGNOSTIC</span><b>0{step+1} / 0{diagnosticQuestions.length}</b></div><div className="diagnostic-progress"><span style={{width:`${((step+1)/diagnosticQuestions.length)*100}%`}}/></div><h3>{q.label}</h3><div className="diagnostic-options">{q.options.map(([value,label])=><button key={value} onClick={()=>answer(q.id,value)}>{label}<ArrowLeft size={16}/></button>)}</div><small>إجابة سريعة — مفيش إجابة غلط.</small></div>;
}
